package com.prisma.music;

import java.io.*;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Bounded metadata reader. Never decodes audio and never modifies source files. */
public final class EmbeddedLyrics {
    private static final int LIMIT=1024*1024, TAG_LIMIT=16*LIMIT;
    private static String ascii(byte[] b,int p,int n){return new String(b,p,n,StandardCharsets.ISO_8859_1);}
    private static long be(byte[] b,int p,int n){long v=0;for(int i=0;i<n;i++)v=(v<<8)|(b[p+i]&255L);return v;}
    private static int sync(byte[] b,int p){int v=0;for(int i=0;i<4;i++)v=(v<<7)|(b[p+i]&127);return v;}
    private static byte[] read(InputStream in,int n)throws IOException {if(n<0||n>TAG_LIMIT)throw new IOException("Metadata too large");byte[] b=new byte[n];new DataInputStream(in).readFully(b);return b;}
    private static void skip(InputStream in,long n)throws IOException {if(n<0)throw new IOException("Invalid size");while(n>0){long k=in.skip(n);if(k>0)n-=k;else {if(in.read()<0)throw new EOFException();n--;}}}
    private static String clean(String s){return s.replace("\u0000","").replace("\uFEFF","").trim();}
    private static boolean lyricKey(String s){return Arrays.asList("LYRICS","UNSYNCEDLYRICS","UNSYNCED LYRICS","SYNCEDLYRICS","SYNCHRONIZEDLYRICS").contains(s.toUpperCase(Locale.ROOT));}
    private static String prefer(String a,String b){return a.isEmpty()||(!a.matches("(?s).*\\[\\d+:\\d{2}.*")&&b.matches("(?s).*\\[\\d+:\\d{2}.*"))?b:a;}
    public static String read(InputStream raw){try {PushbackInputStream in=new PushbackInputStream(raw,12);byte[] h=read(in,12);in.unread(h);if(ascii(h,0,3).equals("ID3"))return id3(in);if(ascii(h,0,4).equals("fLaC"))return flac(in);if(ascii(h,0,4).equals("OggS"))return ogg(in);if(ascii(h,4,4).equals("ftyp"))return boxes(in,Long.MAX_VALUE,0,false);return "";}catch(IOException|RuntimeException e){return "";}}
    private static byte[] deunsync(byte[] b){ByteArrayOutputStream o=new ByteArrayOutputStream();for(int i=0;i<b.length;i++){o.write(b[i]);if((b[i]&255)==255&&i+1<b.length&&b[i+1]==0)i++;}return o.toByteArray();}
    private static int end(byte[] b,int p,int enc){int step=(enc==1||enc==2)?2:1;for(int i=p;i+step<=b.length;i+=step)if(b[i]==0&&(step==1||b[i+1]==0))return i;return b.length;}
    private static String decode(byte[] b,int p,int n,int enc){if(n<=0||n>LIMIT)return "";Charset c=enc==0?StandardCharsets.ISO_8859_1:enc==1?StandardCharsets.UTF_16:enc==2?StandardCharsets.UTF_16BE:StandardCharsets.UTF_8;return clean(new String(b,p,n,c));}
    private static String id3(InputStream in)throws IOException {byte[] h=read(in,10);int version=h[3]&255;if(version<2||version>4)return "";int size=sync(h,6);byte[] data=read(in,size);boolean unsync=(h[5]&128)!=0;if(unsync&&version<4)data=deunsync(data);int p=0;if((h[5]&64)!=0){if(version==2)return "";if(data.length<4)return "";p=version==4?sync(data,0):(int)be(data,0,4)+4;}String result="";int header=version==2?6:10;while(p+header<=data.length){String id=ascii(data,p,version==2?3:4);int len=version==2?(int)be(data,p+3,3):version==4?sync(data,p+4):(int)be(data,p+4,4);if(len<=0||len>data.length-p-header)break;int flags=version==2?0:data[p+9]&255;byte[] b=Arrays.copyOfRange(data,p+header,p+header+len);p+=header+len;if(version==3&&(flags&0xc0)!=0||version==4&&(flags&0x0c)!=0)continue;if(version==4&&(unsync||(flags&2)!=0))b=deunsync(b);int off=version==3&&((flags&32)!=0)||version==4&&((flags&64)!=0)?1:0;if(version==4&&(flags&1)!=0)off+=4;if(off>b.length)continue;b=Arrays.copyOfRange(b,off,b.length);if(b.length>LIMIT||b.length<5)continue;int enc=b[0]&255;if(enc>3)continue;int step=enc==1||enc==2?2:1;if(id.equals("USLT")||id.equals("ULT")){int start=Math.min(b.length,end(b,4,enc)+step);result=prefer(result,decode(b,start,b.length-start,enc));}else if(id.equals("TXXX")||id.equals("TXX")){int e=end(b,1,enc);String key=decode(b,1,e-1,enc);int start=Math.min(b.length,e+step);if(lyricKey(key))result=prefer(result,decode(b,start,b.length-start,enc));}else if((id.equals("SYLT")||id.equals("SLT"))&&b.length>=7){int start=Math.min(b.length,end(b,6,enc)+step);StringBuilder out=new StringBuilder();while(start<b.length){int e=end(b,start,enc),next=e+step;if(next+4>b.length)break;String words=decode(b,start,e-start,enc);long ms=be(b,next,4);if(b[4]==2)out.append(String.format(Locale.ROOT,"[%02d:%02d.%03d]",ms/60000,(ms/1000)%60,ms%1000));out.append(words).append('\n');start=next+4;}result=prefer(result,out.toString().trim());}}return result;}
    private static String comments(byte[] b)throws IOException {DataInputStream in=new DataInputStream(new ByteArrayInputStream(b));int vendor=le(in);skip(in,vendor);int count=le(in);if(count<0||count>10000)return "";String result="";for(int i=0;i<count;i++){int n=le(in);if(n<0||n>LIMIT)return result;String s=new String(read(in,n),StandardCharsets.UTF_8);int eq=s.indexOf('=');if(eq>0&&lyricKey(s.substring(0,eq)))result=prefer(result,clean(s.substring(eq+1)));}return result;}
    private static int le(DataInputStream in)throws IOException{return Integer.reverseBytes(in.readInt());}
    private static String flac(InputStream in)throws IOException {skip(in,4);for(int i=0;i<128;i++){byte[] h=read(in,4);int n=(int)be(h,1,3);if((h[0]&127)==4){String s=comments(read(in,n));if(!s.isEmpty())return s;}else skip(in,n);if((h[0]&128)!=0)break;}return "";}
    private static String ogg(InputStream in)throws IOException {ByteArrayOutputStream packet=new ByteArrayOutputStream();for(int page=0;page<128;page++){byte[] h=read(in,27);if(!ascii(h,0,4).equals("OggS"))return "";byte[] lace=read(in,h[26]&255);for(byte l:lace){int n=l&255;if(packet.size()+n>TAG_LIMIT)return "";packet.write(read(in,n));if(n<255){byte[] b=packet.toByteArray();packet.reset();if(b.length>7&&b[0]==3&&ascii(b,1,6).equals("vorbis"))return comments(Arrays.copyOfRange(b,7,b.length));if(b.length>8&&ascii(b,0,8).equals("OpusTags"))return comments(Arrays.copyOfRange(b,8,b.length));}}}return "";}
    private static String boxes(InputStream in,long remaining,int depth,boolean lyrics)throws IOException {if(depth>8)return "";String result="";String name="";for(int i=0;i<4096&&remaining>=8;i++){byte[] h;try{h=read(in,8);}catch(EOFException e){break;}long size=be(h,0,4);String type=ascii(h,4,4);int head=8;if(size==1){size=be(read(in,8),0,8);head=16;}if(size==0||size<head||size>remaining)return result;long n=size-head;if(type.equals("moov")||type.equals("udta")||type.equals("ilst")||type.equals("\u00a9lyr")||type.equals("----")){result=prefer(result,boxes(in,n,depth+1,lyrics||type.equals("\u00a9lyr")));}else if(type.equals("meta")&&n>=4){skip(in,4);result=prefer(result,boxes(in,n-4,depth+1,lyrics));}else if(type.equals("name")&&n>=4&&n<=LIMIT){byte[] b=read(in,(int)n);name=clean(new String(b,4,b.length-4,StandardCharsets.UTF_8));}else if(type.equals("data")&&(lyrics||lyricKey(name))&&n>=8&&n<=LIMIT){byte[] b=read(in,(int)n);int enc=(int)be(b,0,4)&0xffffff;result=prefer(result,clean(new String(b,8,b.length-8,enc==2?StandardCharsets.UTF_16BE:StandardCharsets.UTF_8)));}else skip(in,n);remaining-=size;}if(depth>0&&remaining>0)skip(in,remaining);return result;}
}
